real_t algorithm_reduce_sum(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    real_t acc = 0.0;
    for (int nl = 0; nl < iterations; nl++) {
        real_t s = 0.0;
        size_t vl = __riscv_vsetvlmax_e32f();
        vfloat32m1_t sum_v = __riscv_vfmv_v_f(vl, 0.0f);

        for (size_t i = 0; i < LEN_1D; i += vl) {
            size_t vl_curr = __riscv_vsetvlmax_e32f();
            if (i + vl_curr > LEN_1D) {
                vl_curr = LEN_1D - i;
            }
            vfloat32m1_t x_chunk = __riscv_vleseg_vx(vl_curr, (vuint8m1_t)(x + i));
            vfloat32m1_t sum_chunk = __riscv_vfmv_v_f(vl_curr, 0.0f);

            for (size_t j = 0; j < vl_curr; j++) {
                vfloat32m1_t val = __riscv_vleseg_vx(1, (vuint8m1_t)(x + i + j));
                sum_chunk = __riscv_vfadd_vv(vl_curr, sum_chunk, val);
            }
            sum_v = __riscv_vfadd_vv(vl_curr, sum_v, sum_chunk);
        }

        s = __riscv_vfmv_f_v(vl, sum_v);
        acc += s;
        dummy(x, NULL, NULL, NULL, NULL, s);
    }
    y[0] = acc / (real_t)(iterations * LEN_1D);

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

