real_t algorithm_scan(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    int iterations_count = iterations / 4 + 1;
    int vlen = __riscv_vlen();
    int vlen_i = vlen / sizeof(Index_type);
    int vlen_f = vlen / sizeof(real_t);
    int loop_count = (LEN_1D + vlen_i - 1) / vlen_i;

    for (int nl = 0; nl < iterations_count; nl++) {
        real_t scan_var = 0.0;

        // Vectorized scan loop
        for (int v = 0; v < loop_count; v++) {
            Index_type i_start = v * vlen_i;
            Index_type i_end = (v + 1) * vlen_i;
            if (i_end > LEN_1D) i_end = LEN_1D;

            int count = i_end - i_start;
            int vl = __riscv_vsetvl_e8m1(count);

            vfloat32m1_t x_v = __riscv_vleil_v(x + i_start, vfloat32m1_t());
            vfloat32m1_t y_v = __riscv_vleil_v(y + i_start, vfloat32m1_t());

            vfloat32m1_t scan_v = __riscv_vfmv_v_f(vl, scan_var, vfloat32m1_t());
            vfloat32m1_t sum_v = __riscv_vadd_vv(vl, scan_v, x_v);

            __riscv_vseil_v(vl, y_v, y + i_start);

            scan_var = __riscv_vfmv_f_v(vl, sum_v, real_t());
        }

        dummy(x, y, NULL, NULL, NULL, scan_var);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

