real_t apps_del_dot_vec_2d(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    real_t half = 0.5f, ptiny = 1.0e-2f;
    int iterations_count = iterations / 4 + 1;

    for (int nl = 0; nl < iterations_count; nl++) {
        // Determine vector length for this iteration
        int vl = __riscv_vsetvlmax();
        if (vl > APPS_N1D) vl = APPS_N1D;

        vfloat32m1_t v_half = __riscv_vfmv_v_f(vl, half);
        vfloat32m1_t v_ptiny = __riscv_vfmv_v_f(vl, ptiny);
        vfloat32m1_t v_one = __riscv_vfmv_v_f(vl, 1.0f);

        for (Index_type i = 0; i < APPS_N1D; i += vl) {
            vfloat32m1_t v_x1, v_x2, v_x3, v_x4;
            vfloat32m1_t v_y1, v_y2, v_y3, v_y4;
            vfloat32m1_t v_fx1, v_fx2, v_fx3, v_fx4;
            vfloat32m1_t v_fy1, v_fy2, v_fy3, v_fy4;

            __riscv_vleif_v(v_x1, apps_x1, vl, i);
            __riscv_vleif_v(v_x2, apps_x2, vl, i);
            __riscv_vleif_v(v_x3, apps_x3, vl, i);
            __riscv_vleif_v(v_x4, apps_x4, vl, i);

            __riscv_vleif_v(v_y1, apps_y1, vl, i);
            __riscv_vleif_v(v_y2, apps_y2, vl, i);
            __riscv_vleif_v(v_y3, apps_y3, vl, i);
            __riscv_vleif_v(v_y4, apps_y4, vl, i);

            __riscv_vleif_v(v_fx1, apps_fx1, vl, i);
            __riscv_vleif_v(v_fx2, apps_fx2, vl, i);
            __riscv_vleif_v(v_fx3, apps_fx3, vl, i);
            __riscv_vleif_v(v_fx4, apps_fx4, vl, i);

            __riscv_vleif_v(v_fy1, apps_fy1, vl, i);
            __riscv_vleif_v(v_fy2, apps_fy2, vl, i);
            __riscv_vleif_v(v_fy3, apps_fy3, vl, i);
            __riscv_vleif_v(v_fy4, apps_fy4, vl, i);

            // Compute xi, xj, yi, yj
            vfloat32m1_t v_sum_x12 = __riscv_vfadd_vv(v_x1, v_x2);
            vfloat32m1_t v_sum_x34 = __riscv_vfadd_vv(v_x3, v_x4);
            vfloat32m1_t v_diff_x = __riscv_vfsub_vv(v_sum_x12, v_sum_x34);
            vfloat32m1_t v_xi = __riscv_vfmul_vf(v_diff_x, v_half);

            vfloat32m1_t v_sum_x23 = __riscv_vfadd_vv(v_x2, v_x3);
            vfloat32m1_t v_sum_x41 = __riscv_vfadd_vv(v_x4, v_x1);
            vfloat32m1_t v_diff_x2 = __riscv_vfsub_vv(v_sum_x23, v_sum_x41);
            vfloat32m1_t v_xj = __riscv_vfmul_vf(v_diff_x2, v_half);

            vfloat32m1_t v_sum_y12 = __riscv_vfadd_vv(v_y1, v_y2);
            vfloat32m1_t v_sum_y34 = __riscv_vfadd_vv(v_y3, v_y4);
            vfloat32m1_t v_diff_y = __riscv_vfsub_vv(v_sum_y12, v_sum_y34);
            vfloat32m1_t v_yi = __riscv_vfmul_vf(v_diff_y, v_half);

            vfloat32m1_t v_sum_y23 = __riscv_vfadd_vv(v_y2, v_y3);
            vfloat32m1_t v_sum_y41 = __riscv_vfadd_vv(v_y4, v_y1);
            vfloat32m1_t v_diff_y2 = __riscv_vfsub_vv(v_sum_y23, v_sum_y41);
            vfloat32m1_t v_yj = __riscv_vfmul_vf(v_diff_y2, v_half);

            // Compute fxi, fxj, fyi, fyj
            vfloat32m1_t v_sum_fx12 = __riscv_vfadd_vv(v_fx1, v_fx2);
            vfloat32m1_t v_sum_fx34 = __riscv_vfadd_vv(v_fx3, v_fx4);
            vfloat32m1_t v_diff_fx = __riscv_vfsub_vv(v_sum_fx12, v_sum_fx34);
            vfloat32m1_t v_fxi = __riscv_vfmul_vf(v_diff_fx, v_half);

            vfloat32m1_t v_sum_fx23 = __riscv_vfadd_vv(v_fx2, v_fx3);
            vfloat32m1_t v_sum_fx41 = __riscv_vfadd_vv(v_fx4, v_fx1);
            vfloat32m1_t v_diff_fx2 = __riscv_vfsub_vv(v_sum_fx23, v_sum_fx41);
            vfloat32m1_t v_fxj = __riscv_vfmul_vf(v_diff_fx2, v_half);

            vfloat32m1_t v_sum_fy12 = __riscv_vfadd_vv(v_fy1, v_fy2);
            vfloat32m1_t v_sum_fy34 = __riscv_vfadd_vv(v_fy3, v_fy4);
            vfloat32m1_t v_diff_fy = __riscv_vfsub_vv(v_sum_fy12, v_sum_fy34);
            vfloat32m1_t v_fyi = __riscv_vfmul_vf(v_diff_fy, v_half);

            vfloat32m1_t v_sum_fy23 = __riscv_vfadd_vv(v_fy2, v_fy3);
            vfloat32m1_t v_sum_fy41 = __riscv_vfadd_vv(v_fy4, v_fy1);
            vfloat32m1_t v_diff_fy2 = __riscv_vfsub_vv(v_sum_fy23, v_sum_fy41);
            vfloat32m1_t v_fyj = __riscv_vfmul_vf(v_diff_fy2, v_half);

            // Compute rarea denominator: xi * yj - xj * yi + ptiny
            vfloat32m1_t v_term1 = __riscv_vfmul_vv(v_xi, v_yj);
            vfloat32m1_t v_term2 = __riscv_vfmul_vv(v_xj, v_yi);
            vfloat32m1_t v_denom = __riscv_vfsub_vv(v_term1, v_term2);
            v_denom = __riscv_vfadd_vf(v_denom, v_ptiny);
            vfloat32m1_t v_rarea = __riscv_vfdiv_vf(v_denom, v_one);

            // Compute dfxdx and dfydy
            vfloat32m1_t v_dfxdx_num = __riscv_vfmul_vv(v_fxi, v_yj);
            vfloat32m1_t v_dfxdx_sub = __riscv_vfmul_vv(v_fxj, v_yi);
            vfloat32m1_t v_dfxdx = __riscv_vfmul_vv(v_rarea, __riscv_vfsub_vv(v_dfxdx_num, v_dfxdx_sub));

            vfloat32m1_t v_dfydy_num = __riscv_vfmul_vv(v_fyj, v_xi);
            vfloat32m1_t v_dfydy_sub = __riscv_vfmul_vv(v_fyi, v_xj);
            vfloat32m1_t v_dfydy = __riscv_vfmul_vv(v_rarea, __riscv_vfsub_vv(v_dfydy_num, v_dfydy_sub));

            // Compute affine term
            vfloat32m1_t v_sum_fy = __riscv_vfadd_vv(v_fy1, v_fy2);
            vfloat32m1_t v_sum_fy2 = __riscv_vfadd_vv(v_sum_fy, v_fy3);
            vfloat32m1_t v_sum_fy3 = __riscv_vfadd_vv(v_sum_fy2, v_fy4);
            vfloat32m1_t v_sum_y = __riscv_vfadd_vv(v_y1, v_y2);
            vfloat32m1_t v_sum_y2 = __riscv_vfadd_vv(v_sum_y, v_y3);
            vfloat32m1_t v_sum_y3 = __riscv_vfadd_vv(v_sum_y2, v_y4);
            vfloat32m1_t v_affine = __riscv_vfdiv_vv(v_sum_fy3, v_sum_y3);

            // Final result
            vfloat32m1_t v_div = __riscv_vfadd_vv(v_dfxdx, v_dfydy);
            v_div = __riscv_vfadd_vv(v_div, v_affine);

            // Store results
            __riscv_vseif_v(v_div, apps_div, vl, i);
        }

        dummy(apps_div, NULL, NULL, NULL, NULL, ptiny);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

