real_t apps_energy(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    real_t rho0 = 1.0f, e_cut = 1.0e-7f, emin = -1.0e15f;
    int iterations_count = iterations / 8 + 1;
    int n = APPS_N1D;

    // Determine vector length
    int vl = __riscv_vsetvlmax();
    int vl_actual = (n < vl) ? n : vl;
    int vl_mask = __riscv_vsetvl(vl_actual);

    for (int nl = 0; nl < iterations_count; nl++) {
        // Loop 1: apps_e_new[i] = apps_e_old[i] - 0.5f * apps_delvc[i] * (apps_p_old[i] + apps_q_old[i]) + 0.5f * apps_work[i];
        {
            vfloat32m1_t v_e_old = __riscv_vleif_v_f32m1(apps_e_old, vl_mask);
            vfloat32m1_t v_delvc = __riscv_vleif_v_f32m1(apps_delvc, vl_mask);
            vfloat32m1_t v_p_old = __riscv_vleif_v_f32m1(apps_p_old, vl_mask);
            vfloat32m1_t v_q_old = __riscv_vleif_v_f32m1(apps_q_old, vl_mask);
            vfloat32m1_t v_work = __riscv_vleif_v_f32m1(apps_work, vl_mask);

            vfloat32m1_t v_sum_pq = __riscv_vfadd_vv(v_p_old, v_q_old, vl_mask);
            vfloat32m1_t v_half = __riscv_vfmv_v_f_f32m1(0.5f, vl_mask);
            vfloat32m1_t v_prod = __riscv_vfmul_vv(v_delvc, v_sum_pq, vl_mask);
            vfloat32m1_t v_sub = __riscv_vfsub_vv(v_e_old, v_prod, vl_mask);
            vfloat32m1_t v_half_work = __riscv_vfmul_vv(v_half, v_work, vl_mask);
            vfloat32m1_t v_result = __riscv_vfadd_vv(v_sub, v_half_work, vl_mask);

            __riscv_vseif_v_f32m1(apps_e_new, v_result, vl_mask);
        }

        // Loop 2: Conditional logic for apps_q_new
        {
            vfloat32m1_t v_delvc = __riscv_vleif_v_f32m1(apps_delvc, vl_mask);
            vfloat32m1_t v_zero = __riscv_vfmv_v_f_f32m1(0.0f, vl_mask);
            vfloat32m1_t v_q_new = __riscv_vfmv_v_f_f32m1(0.0f, vl_mask); // Default to 0.0f

            // Identify where delvc <= 0
            vfloat32m1_t v_le_zero = __riscv_vfclt_vv(v_delvc, __riscv_vfmv_v_f_f32m1(0.0f, vl_mask), vl_mask);
            vfloat32m1_t v_ge_zero = __riscv_vfclt_vv(__riscv_vfmv_v_f_f32m1(0.0f, vl_mask), v_delvc, vl_mask); // delvc > 0

            // Process where delvc <= 0
            vfloat32m1_t v_pbvc = __riscv_vleif_v_f32m1(apps_pbvc, vl_mask);
            vfloat32m1_t v_e_new = __riscv_vleif_v_f32m1(apps_e_new, vl_mask);
            vfloat32m1_t v_bvc = __riscv_vleif_v_f32m1(apps_bvc, vl_mask);
            vfloat32m1_t v_pHalfStep = __riscv_vleif_v_f32m1(apps_pHalfStep, vl_mask);
            vfloat32m1_t v_compHalfStep = __riscv_vleif_v_f32m1(apps_compHalfStep, vl_mask);
            vfloat32m1_t v_ql_old = __riscv_vleif_v_f32m1(apps_ql_old, vl_mask);
            vfloat32m1_t v_qq_old = __riscv_vleif_v_f32m1(apps_qq_old, vl_mask);
            vfloat32m1_t v_rho0 = __riscv_vfmv_v_f_f32m1(rho0, vl_mask);

            // vhalf = 1.0f / (1.0f + apps_compHalfStep[i])
            vfloat32m1_t v_one = __riscv_vfmv_v_f_f32m1(1.0f, vl_mask);
            vfloat32m1_t v_denom = __riscv_vfadd_vv(v_one, v_compHalfStep, vl_mask);
            vfloat32m1_t v_vhalf = __riscv_vfdiv_vv(v_one, v_denom, vl_mask);

            // ssc numerator: apps_pbvc[i] * apps_e_new[i] + vhalf * vhalf * apps_bvc[i] * apps_pHalfStep[i]
            vfloat32m1_t v_pbvc_e = __riscv_vfmul_vv(v_pbvc, v_e_new, vl_mask);
            vfloat32m1_t v_vhalf_sq = __riscv_vfmul_vv(v_vhalf, v_vhalf, vl_mask);
            vfloat32m1_t v_bvc_p = __riscv_vfmul_vv(v_bvc, v_pHalfStep, vl_mask);
            vfloat32m1_t v_vhalf_sq_bvc_p = __riscv_vfmul_vv(v_vhalf_sq, v_bvc_p, vl_mask);
            vfloat32m1_t v_num = __riscv_vfadd_vv(v_pbvc_e, v_vhalf_sq_bvc_p, vl_mask);

            // ssc = num / rho0
            vfloat32m1_t v_ssc = __riscv_vfdiv_vv(v_num, v_rho0, vl_mask);

            // Threshold check: if ssc <= 1.111111e-36f, set to 3.333333e-18f
            vfloat32m1_t v_thresh_low = __riscv_vfmv_v_f_f32m1(1.111111e-36f, vl_mask);
            vfloat32m1_t v_thresh_high = __riscv_vfmv_v_f_f32m1(3.333333e-18f, vl_mask);
            vfloat32m1_t v_is_low = __riscv_vfclt_vv(v_ssc, v_thresh_low, vl_mask);
            vfloat32m1_t v_ssc_masked = __riscv_vfselect_vvv(v_is_low, v_thresh_high, v_ssc, vl_mask);

            // sqrtf(ssc)
            vfloat32m1_t v_sqrt_ssc = __riscv_vfsqrt_vv(v_ssc_masked, vl_mask);

            // apps_q_new[i] = ssc * apps_ql_old[i] + apps_qq_old[i]
            vfloat32m1_t v_ssc_ql = __riscv_vfmul_vv(v_sqrt_ssc, v_ql_old, vl_mask);
            vfloat32m1_t v_q_new_calc = __riscv_vfadd_vv(v_ssc_ql, v_qq_old, vl_mask);

            // Combine: where delvc <= 0, use calculated q_new; else 0.0f
            vfloat32m1_t v_q_new_final = __riscv_vfselect_vvv(v_ge_zero, v_zero, v_q_new_calc, vl_mask);

            __riscv_vseif_v_f32m1(apps_q_new, v_q_new_final, vl_mask);
        }

        // Loop 3: apps_e_new[i] += 0.5f * apps_delvc[i] * ( 3.0f*(apps_p_old[i] + apps_q_old[i]) - 4.0f*(apps_pHalfStep[i] + apps_q_new[i]) );
        {
            vfloat32m1_t v_delvc = __riscv_vleif_v_f32m1(apps_delvc, vl_mask);
            vfloat32m1_t v_p_old = __riscv_vleif_v_f32m1(apps_p_old, vl_mask);
            vfloat32m1_t v_q_old = __riscv_vleif_v_f32m1(apps_q_old, vl_mask);
            vfloat32m1_t v_pHalfStep = __riscv_vleif_v_f32m1(apps_pHalfStep, vl_mask);
            vfloat32m1_t v_q_new = __riscv_vleif_v_f32m1(apps_q_new, vl_mask);

            vfloat32m1_t v_sum_pq = __riscv_vfadd_vv(v_p_old, v_q_old, vl_mask);
            vfloat32m1_t v_sum_phq = __riscv_vfadd_vv(v_pHalfStep, v_q_new, vl_mask);

            vfloat32m1_t v_term1 = __riscv_vfmul_vv(v_sum_pq, __riscv_vfmv_v_f_f32m1(3.0f, vl_mask), vl_mask);
            vfloat32m1_t v_term2 = __riscv_vfmul_vv(v_sum_phq, __riscv_vfmv_v_f_f32m1(4.0f, vl_mask), vl_mask);
            vfloat32m1_t v_diff = __riscv_vfsub_vv(v_term1, v_term2, vl_mask);

            vfloat32m1_t v_half = __riscv_vfmv_v_f_f32m1(0.5f, vl_mask);
            vfloat32m1_t v_prod = __riscv_vfmul_vv(v_delvc, v_diff, vl_mask);
            vfloat32m1_t v_add = __riscv_vfmul_vv(v_half, v_prod, vl_mask);

            vfloat32m1_t v_e_new = __riscv_vleif_v_f32m1(apps_e_new, vl_mask);
            vfloat32m1_t v_e_new_new = __riscv_vfadd_vv(v_e_new, v_add, vl_mask);

            __riscv_vseif_v_f32m1(apps_e_new, v_e_new_new, vl_mask);
        }

        // Loop 4: apps_e_new[i] += 0.5f * apps_work[i]; if (ABS(apps_e_new[i]) < e_cut) apps_e_new[i] = 0.0f; if (apps_e_new[i] < emin) apps_e_new[i] = emin;
        {
            vfloat32m1_t v_delvc = __riscv_vleif_v_f32m1(apps_delvc, vl_mask);
            vfloat32m1_t v_work = __riscv_vleif_v_f32m1(apps_work, vl_mask);
            vfloat32m1_t v_e_new = __riscv_vleif_v_f32m1(apps_e_new, vl_mask);
            vfloat32m1_t v_e_cut = __riscv_vfmv_v_f_f32m1(e_cut, vl_mask);
            vfloat32m1_t v_emin = __riscv_vfmv_v_f_f32m1(emin, vl_mask);
            vfloat32m1_t v_half = __riscv_vfmv_v_f_f32m1(0.5f, vl_mask);

            // Add 0.5 * work
            vfloat32m1_t v_half_work = __riscv_vfmul_vv(v_half, v_work, vl_mask);
            vfloat32m1_t v_e_new_add = __riscv_vfadd_vv(v_e_new, v_half_work, vl_mask);

            // ABS check
            vfloat32m1_t v_abs_e = __riscv_vfabs_vv(v_e_new_add, vl_mask);
            vfloat32m1_t v_is_small = __riscv_vfclt_vv(v_abs_e, v_e_cut, vl_mask);
            vfloat32m1_t v_zero = __riscv_vfmv_v_f_f32m1(0.0f, vl_mask);
            vfloat32m1_t v_e_new_clamped = __riscv_vfselect_vvv(v_is_small, v_zero, v_e_new_add, vl_mask);

            // Emin check
            vfloat32m1_t v_is_min = __riscv_vfclt_vv(v_e_new_clamped, v_emin, vl_mask);
            vfloat32m1_t v_e_new_final = __riscv_vfselect_vvv(v_is_min, v_emin, v_e_new_clamped, vl_mask);

            __riscv_vseif_v_f32m1(apps_e_new, v_e_new_final, vl_mask);
        }

        dummy(apps_e_new, apps_q_new, NULL, NULL, NULL, e_cut);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

