real_t apps_fir(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    Index_type coefflen = APPS_COEFFLEN;
    int iterations_count = iterations / 4 + 1;
    int vl = __riscv_vsetvl_e32f(); // Get current vector length in elements

    for (int nl = 0; nl < iterations_count; nl++) {
        for (Index_type i = 0; i < APPS_N1D; i += vl) {
            vfloat32m1_t acc = __riscv_vfmv_v_f(vl, 0.0f);

            // Process in chunks of vector length
            for (Index_type j = 0; j < coefflen; j += vl) {
                vfloat32m1_t coeff_vec = __riscv_vleig_v_v(vl, (void*)(apps_coeff + j), 0);
                vfloat32m1_t in_vec = __riscv_vleig_v_v(vl, (void*)(apps_in + i + j), 0);
                vfloat32m1_t prod = __riscv_vfmul_vv(vl, coeff_vec, in_vec);
                acc = __riscv_vfadd_vv(vl, acc, prod);
            }

            // Write results back to memory
            vfloat32m1_t out_vec = __riscv_vfmv_v_f(vl, 0.0f);
            for (Index_type k = 0; k < vl; k++) {
                if (i + k < APPS_N1D) {
                    out_vec = __riscv_vset_v_m(vl, out_vec, acc, k, 1);
                } else {
                    out_vec = __riscv_vset_v_m(vl, out_vec, out_vec, k, 0);
                }
            }
            __riscv_vsfm_v_f(vl, (void*)(apps_out + i), out_vec);
        }
        dummy(apps_out, NULL, NULL, NULL, NULL, 0.0f);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

