real_t apps_ltimes_noview(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    Index_type num_d = LTIMES_NUM_D, num_m = LTIMES_NUM_M;
    Index_type num_g = LTIMES_NUM_G, num_z = LTIMES_NUM_Z;

    for (int nl = 0; nl < iterations; nl++) {
        for (Index_type z = 0; z < num_z; ++z)
        for (Index_type g = 0; g < num_g; ++g) {
            // Reorder loops to vectorize over 'm' by iterating 'dd' outside.
            // Original: z, g, m, dd -> Accumulate phidat[m] += elldat[dd+m] * psidat[dd+...]
            // New: z, g, dd, m -> For each dd, vectorize the update over m.

            Index_type z_offset = z * num_m * num_g;
            Index_type g_offset = g * num_m;

            for (Index_type dd = 0; dd < num_d; ++dd) {
                float *phidat_base = &lt_phidat[0 + g_offset + z_offset];
                float *psidat_base = &lt_psidat[dd + g * num_d + z * num_d * num_g];
                float *elldat_base = &lt_elldat[dd]; // elldat[dd + m * num_d] -> base is dd, stride is num_d

                // Determine vector length
                int vl = __riscv_vsetvlmax();

                for (int i = 0; i < num_m; i += vl) {
                    vfloat32m1_t v_elldat = __riscv_vleif_v(vfloat32m1_t(), elldat_base + i, vl);
                    vfloat32m1_t v_psidat = __riscv_vleif_v(vfloat32m1_t(), psidat_base + i, vl);
                    vfloat32m1_t v_phidat = __riscv_vleif_v(vfloat32m1_t(), phidat_base + i, vl);

                    vfloat32m1_t v_prod = __riscv_vmul_vv(v_elldat, v_psidat, vl);
                    vfloat32m1_t v_sum = __riscv_vadd_vv(v_phidat, v_prod, vl);

                    __riscv_vseif_v(v_sum, phidat_base + i, vl);
                }
            }
        }
        dummy(lt_phidat, NULL, NULL, NULL, NULL, 0.0f);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

