real_t apps_matvec_3d_stencil(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    int nl = iterations / 4 + 1;
    size_t vl = __riscv_vsetvlmax();
    size_t nvec = (MV_LEN + vl - 1) / vl;

    for (int i = 0; i < nl; ++i) {
        vfloat32m1_t acc = __riscv_vfmv_v_f(vl, 0.0f);

        // Define pointers for current and x arrays
        float *mv_ptr = (float *)mv_b;
        float *mv_x_ptr = (float *)mv_xdbl;

        // Process 24 multiplications in groups of 4 using vector operations
        for (size_t vec_idx = 0; vec_idx < nvec; ++vec_idx) {
            vfloat32m1_t v_mv = __riscv_vleif_v_f(vl, mv_ptr);
            vfloat32m1_t v_mv_x = __riscv_vleif_v_f(vl, mv_x_ptr);

            // Group 1: mv_b, mv_dbl, mv_dbc, mv_dbr
            vfloat32m1_t v_dbl = __riscv_vleif_v_f(vl, mv_dbl + vec_idx * vl);
            vfloat32m1_t v_dbr = __riscv_vleif_v_f(vl, mv_dbr + vec_idx * vl);
            vfloat32m1_t v_dbc = __riscv_vleif_v_f(vl, mv_dbc + vec_idx * vl);
            vfloat32m1_t v_x_dbl = __riscv_vleif_v_f(vl, mv_xdbl + vec_idx * vl);
            vfloat32m1_t v_x_dbr = __riscv_vleif_v_f(vl, mv_xdbr + vec_idx * vl);
            vfloat32m1_t v_x_dbc = __riscv_vleif_v_f(vl, mv_xdbc + vec_idx * vl);

            vfloat32m1_t t1 = __riscv_vfmacc_v_f_f(vl, v_dbl, v_x_dbl, acc);
            t1 = __riscv_vfmsac_v_f_f(vl, v_dbc, v_x_dbc, t1);
            t1 = __riscv_vfmacc_v_f_f(vl, v_dbr, v_x_dbr, t1);

            // Group 2: mv_c, mv_dcl, mv_dcc, mv_dcr
            vfloat32m1_t v_dcl = __riscv_vleif_v_f(vl, mv_dcl + vec_idx * vl);
            vfloat32m1_t v_dcc = __riscv_vleif_v_f(vl, mv_dcc + vec_idx * vl);
            vfloat32m1_t v_dcr = __riscv_vleif_v_f(vl, mv_dcr + vec_idx * vl);
            vfloat32m1_t v_x_dcl = __riscv_vleif_v_f(vl, mv_xdcl + vec_idx * vl);
            vfloat32m1_t v_x_dcc = __riscv_vleif_v_f(vl, mv_xdcc + vec_idx * vl);
            vfloat32m1_t v_x_dcr = __riscv_vleif_v_f(vl, mv_xdcr + vec_idx * vl);

            t1 = __riscv_vfmacc_v_f_f(vl, v_dcl, v_x_dcl, t1);
            t1 = __riscv_vfmsac_v_f_f(vl, v_dcc, v_x_dcc, t1);
            t1 = __riscv_vfmacc_v_f_f(vl, v_dcr, v_x_dcr, t1);

            // Group 3: mv_c, mv_cbl, mv_cbc, mv_cbr
            vfloat32m1_t v_cbl = __riscv_vleif_v_f(vl, mv_cbl + vec_idx * vl);
            vfloat32m1_t v_cbc = __riscv_vleif_v_f(vl, mv_cbc + vec_idx * vl);
            vfloat32m1_t v_cbr = __riscv_vleif_v_f(vl, mv_cbr + vec_idx * vl);
            vfloat32m1_t v_x_cbl = __riscv_vleif_v_f(vl, mv_xcbl + vec_idx * vl);
            vfloat32m1_t v_x_cbc = __riscv_vleif_v_f(vl, mv_xcbc + vec_idx * vl);
            vfloat32m1_t v_x_cbr = __riscv_vleif_v_f(vl, mv_xcbr + vec_idx * vl);

            t1 = __riscv_vfmacc_v_f_f(vl, v_cbl, v_x_cbl, t1);
            t1 = __riscv_vfmsac_v_f_f(vl, v_cbc, v_x_cbc, t1);
            t1 = __riscv_vfmacc_v_f_f(vl, v_cbr, v_x_cbr, t1);

            // Group 4: mv_c, mv_ccl, mv_ccc, mv_ccr
            vfloat32m1_t v_ccl = __riscv_vleif_v_f(vl, mv_ccl + vec_idx * vl);
            vfloat32m1_t v_ccc = __riscv_vleif_v_f(vl, mv_ccc + vec_idx * vl);
            vfloat32m1_t v_ccr = __riscv_vleif_v_f(vl, mv_ccr + vec_idx * vl);
            vfloat32m1_t v_x_ccl = __riscv_vleif_v_f(vl, mv_xccl + vec_idx * vl);
            vfloat32m1_t v_x_ccc = __riscv_vleif_v_f(vl, mv_xccc + vec_idx * vl);
            vfloat32m1_t v_x_ccr = __riscv_vleif_v_f(vl, mv_xccr + vec_idx * vl);

            t1 = __riscv_vfmacc_v_f_f(vl, v_ccl, v_x_ccl, t1);
            t1 = __riscv_vfmsac_v_f_f(vl, v_ccc, v_x_ccc, t1);
            t1 = __riscv_vfmacc_v_f_f(vl, v_ccr, v_x_ccr, t1);

            // Group 5: mv_c, mv_cfl, mv_cfc, mv_cfr
            vfloat32m1_t v_cfl = __riscv_vleif_v_f(vl, mv_cfl + vec_idx * vl);
            vfloat32m1_t v_cfc = __riscv_vleif_v_f(vl, mv_cfc + vec_idx * vl);
            vfloat32m1_t v_cfr = __riscv_vleif_v_f(vl, mv_cfr + vec_idx * vl);
            vfloat32m1_t v_x_cfl = __riscv_vleif_v_f(vl, mv_xcfl + vec_idx * vl);
            vfloat32m1_t v_x_cfc = __riscv_vleif_v_f(vl, mv_xcfc + vec_idx * vl);
            vfloat32m1_t v_x_cfr = __riscv_vleif_v_f(vl, mv_xcfr + vec_idx * vl);

            t1 = __riscv_vfmacc_v_f_f(vl, v_cfl, v_x_cfl, t1);
            t1 = __riscv_vfmsac_v_f_f(vl, v_cfc, v_x_cfc, t1);
            t1 = __riscv_vfmacc_v_f_f(vl, v_cfr, v_x_cfr, t1);

            // Group 6: mv_u, mv_ubl, mv_ubc, mv_ubr
            vfloat32m1_t v_ubl = __riscv_vleif_v_f(vl, mv_ubl + vec_idx * vl);
            vfloat32m1_t v_ubc = __riscv_vleif_v_f(vl, mv_ubc + vec_idx * vl);
            vfloat32m1_t v_ubr = __riscv_vleif_v_f(vl, mv_ubr + vec_idx * vl);
            vfloat32m1_t v_x_ubl = __riscv_vleif_v_f(vl, mv_xubl + vec_idx * vl);
            vfloat32m1_t v_x_ubc = __riscv_vleif_v_f(vl, mv_xubc + vec_idx * vl);
            vfloat32m1_t v_x_ubr = __riscv_vleif_v_f(vl, mv_xubr + vec_idx * vl);

            t1 = __riscv_vfmacc_v_f_f(vl, v_ubl, v_x_ubl, t1);
            t1 = __riscv_vfmsac_v_f_f(vl, v_ubc, v_x_ubc, t1);
            t1 = __riscv_vfmacc_v_f_f(vl, v_ubr, v_x_ubr, t1);

            // Group 7: mv_u, mv_ucl, mv_ucc, mv_ucc
            vfloat32m1_t v_ucl = __riscv_vleif_v_f(vl, mv_ucl + vec_idx * vl);
            vfloat32m1_t v_ucc = __riscv_vleif_v_f(vl, mv_ucc + vec_idx * vl);
            vfloat32m1_t v_ucc_r = __riscv_vleif_v_f(vl, mv_ucc + vec_idx * vl); // Reuse v_ucc for mv_ucc
            vfloat32m1_t v_x_ucl = __riscv_vleif_v_f(vl, mv_xucl + vec_idx * vl);
            vfloat32m1_t v_x_ucc = __riscv_vleif_v_f(vl, mv_xucc + vec_idx * vl);
            vfloat32m1_t v_x_ucc_r = __riscv_vleif_v_f(vl, mv_xucc + vec_idx * vl);

            t1 = __riscv_vfmacc_v_f_f(vl, v_ucl, v_x_ucl, t1);
            t1 = __riscv_vfmsac_v_f_f(vl, v_ucc, v_x_ucc, t1);
            t1 = __riscv_vfmacc_v_f_f(vl, v_ucc_r, v_x_ucc_r, t1);

            // Group 8: mv_u, mv_ufl, mv_ufc, mv_ufr
            vfloat32m1_t v_ufl = __riscv_vleif_v_f(vl, mv_ufl + vec_idx * vl);
            vfloat32m1_t v_ufc = __riscv_vleif_v_f(vl, mv_ufc + vec_idx * vl);
            vfloat32m1_t v_ufr = __riscv_vleif_v_f(vl, mv_ufr + vec_idx * vl);
            vfloat32m1_t v_x_ufl = __riscv_vleif_v_f(vl, mv_xufl + vec_idx * vl);
            vfloat32m1_t v_x_ufc = __riscv_vleif_v_f(vl, mv_xufc + vec_idx * vl);
            vfloat32m1_t v_x_ufr = __riscv_vleif_v_f(vl, mv_xufr + vec_idx * vl);

            t1 = __riscv_vfmacc_v_f_f(vl, v_ufl, v_x_ufl, t1);
            t1 = __riscv_vfmsac_v_f_f(vl, v_ufc, v_x_ufc, t1);
            t1 = __riscv_vfmacc_v_f_f(vl, v_ufr, v_x_ufr, t1);

            // Store result
            __riscv_vseif_v_f(vl, t1, mv_ptr);
            mv_ptr += vl;
            mv_x_ptr += vl;
        }
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

