real_t apps_nodal_accumulation_3d(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    int nl = iterations / 4 + 1;
    int i;
    real_t val;
    vfloat32m1_t vx0, vx1, vx2, vx3, vx4, vx5, vx6, vx7;

    // Load pointers
    vfloat32m1_t *px0 = (vfloat32m1_t *)apps_x0;
    vfloat32m1_t *px1 = (vfloat32m1_t *)apps_x1;
    vfloat32m1_t *px2 = (vfloat32m1_t *)apps_x2;
    vfloat32m1_t *px3 = (vfloat32m1_t *)apps_x3;
    vfloat32m1_t *px4 = (vfloat32m1_t *)apps_x4;
    vfloat32m1_t *px5 = (vfloat32m1_t *)apps_x5;
    vfloat32m1_t *px6 = (vfloat32m1_t *)apps_x6;
    vfloat32m1_t *px7 = (vfloat32m1_t *)apps_x7;
    vfloat32m1_t *pvol = (vfloat32m1_t *)apps_vol;

    // Determine vector length
    size_t vl = vsetvl_e32m1(APPS_N1D);

    for (i = 0; i < nl; ++i) {
        // Load 8 elements from apps_vol
        vx0 = vld_v_f_f32m1(vl, pvol);
        pvol += vl;

        // Broadcast the loaded value to all 8 lanes
        vx1 = vx0;
        vx2 = vx0;
        vx3 = vx0;
        vx4 = vx0;
        vx5 = vx0;
        vx6 = vx0;
        vx7 = vx0;

        // Store the broadcasted values to apps_x0 through apps_x7
        vst_v_f_f32m1(vl, px0, vx0);
        vst_v_f_f32m1(vl, px1, vx1);
        vst_v_f_f32m1(vl, px2, vx2);
        vst_v_f_f32m1(vl, px3, vx3);
        vst_v_f_f32m1(vl, px4, vx4);
        vst_v_f_f32m1(vl, px5, vx5);
        vst_v_f_f32m1(vl, px6, vx6);
        vst_v_f_f32m1(vl, px7, vx7);

        px0 += vl;
        px1 += vl;
        px2 += vl;
        px3 += vl;
        px4 += vl;
        px5 += vl;
        px6 += vl;
        px7 += vl;
    }

    // Handle remaining elements if APPS_N1D is not a multiple of 8
    size_t rem = APPS_N1D % 8;
    if (rem > 0) {
        size_t rem_idx = APPS_N1D - rem;
        for (i = 0; i < rem; ++i) {
            val = 0.125f * apps_vol[rem_idx + i];
            apps_x0[rem_idx + i] = val;
            apps_x1[rem_idx + i] = val;
            apps_x2[rem_idx + i] = val;
            apps_x3[rem_idx + i] = val;
            apps_x4[rem_idx + i] = val;
            apps_x5[rem_idx + i] = val;
            apps_x6[rem_idx + i] = val;
            apps_x7[rem_idx + i] = val;
