real_t apps_pressure(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    real_t cls = 1.0f, p_cut = 1.0e-7f, pmin = 0.0f, eosvmax = 1.0e9f;
    int nl_limit = iterations / 4 + 1;
    int n = APPS_N1D;

    for (int nl = 0; nl < nl_limit; nl++) {
        // Loop 1: apps_bvc[i] = cls * (apps_compression[i] + 1.0f)
        {
            size_t vl = __riscv_vsetvl_e32f(n);
            vfloat32m1_t vcls = __riscv_vfmv_v_f(vl, cls);
            vfloat32m1_t vone = __riscv_vfmv_v_f(vl, 1.0f);
            vfloat32m1_t vcomp = __riscv_vleop_v_f(vl, vone, vfloat32m1_t){ .v = apps_compression };
            vfloat32m1_t vsum = __riscv_vadd_vv(vl, vcomp, vone);
            vfloat32m1_t vbvc = __riscv_vfmul_vv(vl, vcls, vsum);
            __riscv_vseop_v(vl, vbvc, apps_bvc);
        }

        // Loop 2: Compute p with conditional logic
        {
            size_t vl = __riscv_vsetvl_e32f(n);
            vfloat32m1_t vcut = __riscv_vfmv_v_f(vl, p_cut);
            vfloat32m1_t vzero = __riscv_vfmv_v_f(vl, 0.0f);
            vfloat32m1_t vone = __riscv_vfmv_v_f(vl, 1.0f);
            vfloat32m1_t veosvmax = __riscv_vfmv_v_f(vl, eosvmax);
            vfloat32m1_t vpmin = __riscv_vfmv_v_f(vl, pmin);

            vfloat32m1_t vbvc = __riscv_vleop_v_f(vl, vone, vfloat32m1_t){ .v = apps_bvc };
            vfloat32m1_t veold = __riscv_vleop_v_f(vl, vone, vfloat32m1_t){ .v = apps_e_old };
            vfloat32m1_t vp = __riscv_vfmul_vv(vl, vbvc, veold);

            // if (ABS(p) < p_cut) p = 0.0f;
            vfloat32m1_t vabs_p = __riscv_vfabs_vv(vl, vp, vp);
            vfloat32m1_t vcond1 = __riscv_vclt_vv(vl, vabs_p, vcut);
            vfloat32m1_t vmask1 = __riscv_vand_vv(vl, vcond1, vcond1);
            vp = __riscv_vwmulu_vv(vl, vp, vmask1); // Zero where condition is true
            vp = __riscv_vsub_vv(vl, vp, vzero);     // Ensure zero

            // if (apps_vnewc[i] >= eosvmax) p = 0.0f;
            vfloat32m1_t vvnewc = __riscv_vleop_v_f(vl, vone, vfloat32m1_t){ .v = apps_vnewc };
            vfloat32m1_t vcond2 = __riscv_vge_vv(vl, vvnewc, veosvmax);
            vfloat32m1_t vmask2 = __riscv_vand_vv(vl, vcond2, vcond2);
            vp = __riscv_vwmulu_vv(vl, vp, vmask2);
            vp = __riscv_vsub_vv(vl, vp, vzero);

            // if (p < pmin) p = pmin;
            vfloat32m1_t vcond3 = __riscv_vclt_vv(vl, vp, vpmin);
            vfloat32m1_t vmask3 = __riscv_vand_vv(vl, vcond3, vcond3);
            vp = __riscv_vwmulu_vv(vl, vp, vmask3);
            vp = __riscv_vadd_vv(vl, vp, vpmin);

            __riscv_vseop_v(vl, vp, apps_p_new);
        }

        dummy(apps_p_new, apps_bvc, NULL, NULL, NULL, p_cut);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

