        vfloat32m1_t vy7, vy1, vy2, vy4, vy3, vy0, vy5, vy6;
        vfloat32m1_t vz7, vz1, vz2, vz4, vz3, vz0, vz5, vz6;

        vx7 = __riscv_vle32_v_f32m1(apps_x7, vl);
        vx1 = __riscv_vle32_v_f32m1(apps_x1, vl);
        vx2 = __riscv_vle32_v_f32m1(apps_x2, vl);
        vx4 = __riscv_vle32_v_f32m1(apps_x4, vl);
        vx3 = __riscv_vle32_v_f32m1(apps_x3, vl);
        vx0 = __riscv_vle32_v_f32m1(apps_x0, vl);
        vx5 = __riscv_vle32_v_f32m1(apps_x5, vl);
        vx6 = __riscv_vle32_v_f32m1(apps_x6, vl);

        vy7 = __riscv_vle32_v_f32m1(apps_y7, vl);
        vy1 = __riscv_vle32_v_f32m1(apps_y1, vl);
        vy2 = __riscv_vle32_v_f32m1(apps_y2, vl);
        vy4 = __riscv_vle32_v_f32m1(apps_y4, vl);
        vy3 = __riscv_vle32_v_f32m1(apps_y3, vl);
        vy0 = __riscv_vle32_v_f32m1(apps_y0, vl);
        vy5 = __riscv_vle32_v_f32m1(apps_y5, vl);
        vy6 = __riscv_vle32_v_f32m1(apps_y6, vl);

        vz7 = __riscv_vle32_v_f32m1(apps_z7, vl);
        vz1 = __riscv_vle32_v_f32m1(apps_z1, vl);
        vz2 = __riscv_vle32_v_f32m1(apps_z2, vl);
        vz4 = __riscv_vle32_v_f32m1(apps_z4, vl);
        vz3 = __riscv_vle32_v_f32m1(apps_z3, vl);
        vz0 = __riscv_vle32_v_f32m1(apps_z0, vl);
        vz5 = __riscv_vle32_v_f32m1(apps_z5, vl);
        vz6 = __riscv_vle32_v_f32m1(apps_z6, vl);

        // Compute differences: x7 - x1, x7 - x2, x7 - x4, etc.
        vx71 = __riscv_vsub_v_f32m1(vx7, vx1);
        vx72 = __riscv_vsub_v_f32m1(vx7, vx2);
        vx74 = __riscv_vsub_v_f32m1(vx7, vx4);
        vx30 = __riscv_vsub_v_f32m1(vx3, vx0);
        vx50 = __riscv_vsub_v_f32m1(vx5, vx0);
        vx60 = __riscv_vsub_v_f32m1(vx6, vx0);

        vy71 = __riscv_vsub_v_f32m1(vy7, vy1);
        vy72 = __riscv_vsub_v_f32m1(vy7, vy2);
        vy74 = __riscv_vsub_v_f32m1(vy7, vy4);
        vy30 = __riscv_vsub_v_f32m1(vy3, vy0);
        vy50 = __riscv_vsub_v_f32m1(vy5, vy0);
        vy60 = __riscv_vsub_v_f32m1(vy6, vy0);

        vz71 = __riscv_vsub_v_f32m1(vz7, vz1);
        vz72 = __riscv_vsub_v_f32m1(vz7, vz2);
        vz74 = __riscv_vsub_v_f32m1(vz7, vz4);
        vz30 = __riscv_vsub_v_f32m1(vz3, vz0);
        vz50 = __riscv_vsub_v_f32m1(vz5, vz0);
        vz60 = __riscv_vsub_v_f32m1(vz6, vz0);

        // First term: (x71+x60, y71+y60, z71+z60) . cross(x72, x30)
        vxps = __riscv_vadd_v_f32m1(vx71, vx60);
        vyps = __riscv_vadd_v_f32m1(vy71, vy60);
        vzps = __riscv_vadd_v_f32m1(vz71, vz60);

        vcyz = __riscv_vfmacc_v_f32m1(vy72, vz30, vzero);
        vcyz = __riscv_vfmsub_v_f32m1(vcyz, vz72, vy30); // y72*z30 - z72*y30
        vczx = __riscv_vfmacc_v_f32m1(vz72, vx30, vzero);
        vczx = __riscv_vfmsub_v_f32m1(vczx, vx72, vz30); // z72*x30 - x72*z30
        vcxy = __riscv_vfmacc_v_f32m1(vx72, vy30, vzero);
        vcxy = __riscv_vfmsub_v_f32m1(vcxy, vy72, vx30); // x72*y30 - y72*x30

        vterm1 = __riscv_vfmacc_v_f32m1(vxps, vcyz, vzero);
        vterm1 = __riscv_vfmacc_v_f32m1(vyps, vczx, vterm1);
        vterm1 = __riscv_vfmacc_v_f32m1(vzps, vcxy, vterm1);

        // Second term: (x72+x50, y72+y50, z72+z50) . cross(x74, x60)
        vxps = __riscv_vadd_v_f32m1(vx72, vx50);
        vyps = __riscv_vadd_v_f32m1(vy72, vy50);
        vzps = __riscv_vadd_v_f32m1(vz72, vz50);

        vcyz = __riscv_vfmacc_v_f32m1(vy74, vz60, vzero);
        vcyz = __riscv_vfmsub_v_f32m1(vcyz, vz74, vy60);
        vczx = __riscv_vfmacc_v_f32m1(vz74, vx60, vzero);
        vczx = __riscv_vfmsub_v_f32m1(vczx, vx74, vz60);
        vcxy = __riscv_vfmacc_v_f32m1(vx74, vy60, vzero);
        vcxy = __riscv_vfmsub_v_f32m1(vcxy, vy74, vx60);

        vterm2 = __riscv_vfmacc_v_f32m1(vxps, vcyz, vzero);
        vterm2 = __riscv_vfmacc_v_f32m1(vyps, vczx, vterm2);
        vterm2 = __riscv_vfmacc_v_f32m1(vzps, vcxy, vterm2);

        // Third term: (x74+x30, y74+y30, z74+z30) . cross(x71, x50)
        vxps = __riscv_vadd_v_f32m1(vx74, vx30);
        vyps = __riscv_vadd_v_f32m1(vy74, vy30);
        vzps = __riscv_vadd_v_f32m1(vz74, vz30);

        vcyz = __riscv_vfmacc_v_f32m1(vy71, vz50, vzero);
        vcyz = __riscv_vfmsub_v_f32m1(vcyz, vz71, vy50);
        vczx = __riscv_vfmacc_v_f32m1(vz71, vx50, vzero);
        vczx = __riscv_vfmsub_v_f32m1(vczx, vx71, vz50);
        vcxy = __riscv_vfmacc_v_f32m1(vx71, vy50, vzero);
        vcxy = __riscv_vfmsub_v_f32m1(vcxy, vy71, vx50);

        vterm3 = __riscv_vfmacc_v_f32m1(vxps, vcyz, vzero);
        vterm3 = __riscv_vfmacc_v_f32m1(vyps, vczx, vterm3);
        vterm3 = __riscv_vfmacc_v_f32m1(vzps, vcxy, vterm3);

        // Sum terms
        vv_sum = __riscv_vfadd_v_f32m1(vterm1, vterm2);
        vv_sum = __riscv_vfadd_v_f32m1(vv_sum, vterm3);

        // Scale and store
        vv_scaled = __riscv_vfmul_v_f32m1(vv_sum, vnormq);
        __riscv_vse32_v_f32m1(apps_vol, vv_scaled, vl);

        // Dummy call with vector result? The original passes NULLs and vnormq.
        // We must preserve the call signature and behavior.
        dummy(apps_vol, NULL, NULL, NULL, NULL, vnormq);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

