real_t basic_if_quad(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    for (int nl = 0; nl < iterations; nl++) {
        size_t vl = __riscv_vsetvlmax_e32m1();
        vfloat32m1_t vzero = __riscv_vfmv_v_f_f32m1(0.0f, vl);
        vfloat32m1_t vtwo = __riscv_vfmv_v_f_f32m1(2.0f, vl);
        vfloat32m1_t vfour = __riscv_vfmv_v_f_f32m1(4.0f, vl);
        vfloat32m1_t vone = __riscv_vfmv_v_f_f32m1(1.0f, vl);

        for (Index_type i = 0; i < LEN_1D; i += vl) {
            vfloat32m1_t v_b = __riscv_vleif_v_f32m1(vl, b + i, vzero);
            vfloat32m1_t v_a = __riscv_vleif_v_f32m1(vl, a + i, vzero);
            vfloat32m1_t v_c = __riscv_vleif_v_f32m1(vl, c + i, vzero);

            vfloat32m1_t v_b2 = __riscv_vfmul_vv(v_b, v_b);
            vfloat32m1_t v_ac = __riscv_vfmul_vv(v_a, v_c);
            vfloat32m1_t v_4ac = __riscv_vfmul_vf(v_ac, vfour);
            vfloat32m1_t v_s = __riscv_vfsub_vv(v_b2, v_4ac);

            // Create mask: 1.0 where s >= 0, 0.0 otherwise
            // vsgnjx(x, y): if x >= 0, result = y; else result = -y
            // We want 1.0 if s >= 0. So if s >= 0, result = 1.0 (vone). Else result = -1.0 (vzero - vone).
            // Actually simpler: vsgnjx(s, vone) gives vone if s>=0, -vone if s<0.
            // Then we can use vmsltu or similar to invert, or just use the sign bit logic directly.
            // Let's use: mask = (s >= 0) ? 1.0 : 0.0
            // vsgnjx(s, vone) -> [1.0, -1.0]
            // vfneg(vsgnjx(s, vone), vzero) -> [-1.0, 1.0]
            // vmsltu(vsgnjx(s, vone), vzero) -> [0, 1] if we compare with 0? No.
            // Simpler approach:
            // v_sign = vsgnjx(s, vzero) -> [0.0, s] (sign bit extracted as magnitude of s if s<0, else 0)
            // This doesn't give a clean 1/0 mask easily without more ops.
            // Standard trick:
            // mask = vmsltu(vsgnjx(s, vone), vzero) ? No.
            // Let's do:
            // v_temp = vsgnjx(s, vone); // [1.0, -1.0]
            // v_mask = vmsltu(v_temp, vzero); // If temp < 0 (i.e. s<0), result 1. Else 0.
            // We want inverse: if s>=0 (temp>=0), result 1.
            // So v_mask = vmsltu(vzero, v_temp); // If 0 < temp (s>0), result 1. If temp==0 (s==0), result 0?
            // vmsltu is unsigned less than. 0 < 1.0 is true (1). 0 < -1.0 (0xFFFFFFFF) is false (0).
            // So vmsltu(vzero, v_temp) gives 1 if s>0, 0 if s<=0.
            // We need s>=0.
            // vmsleu(vzero, v_temp) gives 1 if 0 <= temp.
            // 0 <= 1.0 -> 1. 0 <= -1.0 (large unsigned) -> 1. This is wrong for negative.
            // Wait, -1.0 in float is 0xBF800000. As uint32, it's 0xBF800000.
            // 0 <= 0xBF800000 is true.
            // Let's re-evaluate vsgnjx behavior.
            // vsgnjx(x, y): if x >= 0, result = y. Else result = -y.
            // s >= 0 -> result = vone (1.0).
            // s < 0 -> result = -vone (-1.0).
            // We want mask = 1.0 if s>=0, else 0.0.
            // We have v_temp = [1.0, -1.0].
            // We need to convert [1.0, -1.0] to [1.0, 0.0].
            // vmsltu(x, y): returns 1.0 if x < y (unsigned), else 0.0.
            // Compare v_temp with vzero (0.0).
            // 1.0 < 0.0 (unsigned)? 0x3F800000 < 0x00000000 -> False -> 0.0.
            // -1.0 < 0.0 (unsigned)? 0xBF800000 < 0x00000000 -> False -> 0.0.
            // This doesn't work.
            // Try vmsleu(vzero, v_temp): 0 <= 1.0 (True -> 1.0). 0 <= -1.0 (True -> 1.0). No.
            // Try vmsltu(vzero, v_temp): 0 < 1.0 (True -> 1.0). 0 < -1.0 (False -> 0.0).
            // This gives 1.0 for s>0, 0.0 for s<0.
            // We need to handle s==0. If s==0, vsgnjx returns vone (1.0).
            // vmsltu(vzero, 1.0) -> 1.0. Correct.
            // So vmsltu(vzero, v_temp) works for s>0 and s=0?
            // If s=0, v_temp=1.0. 0 < 1.0 is true. Result 1.0. Correct.
            // If s<0, v_temp=-1.0. 0 < -1.0 (unsigned) is false. Result 0.0. Correct.
            // So mask = vmsltu(vzero, vsgnjx(s, vone)).

            vfloat32m1_t v_temp = __riscv_vfsgnjx_vv(v_s, vone);
            vfloat32m1_t v_mask = __riscv_vmsltu_vv(vzero, v_temp);

            vfloat32m1_t v_sqrt_s = __riscv_vfmsqrt_vf(v_s, vzero);
            vfloat32m1_t v_s_masked = __riscv_vfmsub_vv(v_sqrt_s, v_mask, vzero);

            vfloat32m1_t v_neg_b = __riscv_vfneg_vv(v_b, vzero);
            vfloat32m1_t v_num1 = __riscv_vfadd_vv(v_neg_b, v_s_masked);
            vfloat32m1_t v_num2 = __riscv_vfsub_vv(v_neg_b, v_s_masked);
            vfloat32m1_t v_denom = __riscv_vfmul_vf(v_a, vtwo);

            vfloat32m1_t v_out2 = __riscv_vfdiv_vv(v_num1, v_denom);
            vfloat32m1_t v_out1 = __riscv_vfdiv_vv(v_num2, v_denom);

            // Apply mask: if s>=0, keep value, else 0.0
            vfloat32m1_t v_out2_final = __riscv_vfmsub_vv(v_out2, v_mask, vzero);
            vfloat32m1_t v_out1_final = __riscv_vfmsub_vv(v_out1, v_mask, vzero);

            __riscv_vseif_v_f32m1(vl, out2 + i, v_out2_final, vzero);
            __riscv_vseif_v_f32m1(vl, out1 + i, v_out1_final, vzero);
        }

        dummy(out1, out2, a, b, c, 0.0);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

