    for (int nl = 0; nl < iterations; nl++) {
        Index_type len = LEN_1D;
        vlenb = vsetvlmax(vtype_mmask, 0);

        // Process in vector chunks
        for (Index_type i = 0; i < len; i += vlenb) {
            Index_type vl = vsetvlmax(vtype_mmask, 0);
            vint16m1_t in1_v = vle16_v(vl, &in1[i]);
            vint16m1_t in2_v = vle16_v(vl, &in2[i]);
            vint16m1_t neg_in1_v = vneg_v(vl, in1_v);
            vint16m1_t neg_in2_v = vneg_v(vl, in2_v);
            vint16m1_t sum_v = vadd_v(vl, neg_in1_v, neg_in2_v);
            vint16m1_t out_v = vsub_v(vl, sum_v, vzero); // -in1 - in2 = -(in1 + in2)

            vse16_v(vl, out_v, &out1[i]);
            vse16_v(vl, out_v, &out2[i]);
            vse16_v(vl, out_v, &out3[i]);
        }

        dummy(out1, out2, out3, in1, in2, 0.0);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

