real_t basic_muladdsub(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    for (int nl = 0; nl < iterations; nl++) {
        Index_type len = LEN_1D;
        size_t vl = __riscv_vsetvlmax();
        size_t vl_bytes = vl * sizeof(float);
        size_t remaining = len;

        while (remaining >= vl_bytes) {
            vfloat32m1_t v_in1 = __riscv_vle8f_v(vl, (const float *)in1);
            vfloat32m1_t v_in2 = __riscv_vle8f_v(vl, (const float *)in2);
            vfloat32m1_t v_out1 = __riscv_vfmul_vv(v_in1, v_in2);
            vfloat32m1_t v_out2 = __riscv_vfadd_vv(v_in1, v_in2);
            vfloat32m1_t v_out3 = __riscv_vfsub_vv(v_in1, v_in2);
            __riscv_vse8f_v(vl, v_out1, (float *)out1);
            __riscv_vse8f_v(vl, v_out2, (float *)out2);
            __riscv_vse8f_v(vl, v_out3, (float *)out3);
            in1 += vl_bytes / sizeof(float);
            in2 += vl_bytes / sizeof(float);
            out1 += vl_bytes / sizeof(float);
            out2 += vl_bytes / sizeof(float);
            out3 += vl_bytes / sizeof(float);
            remaining -= vl_bytes;
        }

        if (remaining > 0) {
            vfloat32m1_t v_in1 = __riscv_vle8f_v(remaining, (const float *)in1);
            vfloat32m1_t v_in2 = __riscv_vle8f_v(remaining, (const float *)in2);
            vfloat32m1_t v_out1 = __riscv_vfmul_vv(v_in1, v_in2);
            vfloat32m1_t v_out2 = __riscv_vfadd_vv(v_in1, v_in2);
            vfloat32m1_t v_out3 = __riscv_vfsub_vv(v_in1, v_in2);
            __riscv_vse8f_v(remaining, v_out1, (float *)out1);
            __riscv_vse8f_v(remaining, v_out2, (float *)out2);
            __riscv_vse8f_v(remaining, v_out3, (float *)out3);
        }

        dummy(out1, out2, out3, in1, in2, 0.0);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

