real_t basic_nested_init(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    Index_type nk = 8, nj = LEN_2D, ni = LEN_2D;
    int nl_count = iterations / 32 + 1;

    // Precompute scalar multiplier
    real_t scale = 0.00000001;

    for (int nl = 0; nl < nl_count; nl++) {
        // Determine vector length for this iteration
        // vlen_t is the type for vector length, __riscv_vsetvl returns it
        vlen_t vl = __riscv_vsetvl_e32f(ni);

        for (Index_type k = 0; k < nk; ++k) {
            for (Index_type j = 0; j < nj; ++j) {
                // Base address for the current (k, j) plane along i
                // array3d[i + ni*(j + nj*k)]
                // Let base = j + nj*k
                Index_type base = j + nj * k;
                real_t *ptr = &array3d[base * ni];

                // Load factors j and k as vectors
                vfloat32m1_t vj = __riscv_vfmv_v_f(vl, (real_t)j);
                vfloat32m1_t vk = __riscv_vfmv_v_f(vl, (real_t)k);

                // Create vector of i: 0, 1, 2, ...
                vfloat32m1_t vi = __riscv_vmv_v_x(vl, 0);

                // Compute i * j * k * scale
                // First i * j
                vfloat32m1_t tmp = __riscv_vfmul_vv(vl, vi, vj);
                // Then * k
                tmp = __riscv_vfmul_vv(vl, tmp, vk);
                // Then * scale
                vfloat32m1_t vscale = __riscv_vfmv_v_f(vl, scale);
                tmp = __riscv_vfmul_vv(vl, tmp, vscale);

                // Store to memory
                // We need to store to ptr[0...ni-1]
                // Since we computed the whole vector, we can store directly
                __riscv_vse_v_x(ptr, tmp);
            }
        }

        dummy(array3d, NULL, NULL, NULL, NULL, 0.0);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

