real_t basic_pi_atomic(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    real_t dx = 1.0 / (real_t)LEN_1D;
    real_t pi_acc = 0.0;
    int iterations_val = iterations;
    int len_val = LEN_1D;

    for (int nl = 0; nl < iterations_val; nl++) {
        real_t pi = 0.0;

        int i = 0;
        while (i < len_val) {
            int vlen = __riscv_vsetvl_e32f(len_val - i);
            vfloat32m1_t vx = __riscv_vle32_v_f32m1((void*)&i, vlen);
            vfloat32m1_t vdx = __riscv_vfmv_v_f_f32m1(vlen, dx);
            vfloat32m1_t vhalf = __riscv_vfmv_v_f_f32m1(vlen, 0.5f);

            vfloat32m1_t v_xv = __riscv_vfadd_v_f_f32m1(vx, vhalf);
            v_xv = __riscv_vfmul_vv_f32m1(v_xv, vdx);

            vfloat32m1_t v_xv_sq = __riscv_vfmul_vv_f32m1(v_xv, v_xv);
            vfloat32m1_t v_one = __riscv_vfmv_v_f_f32m1(vlen, 1.0f);
            vfloat32m1_t v_denom = __riscv_vfadd_vv_f32m1(v_one, v_xv_sq);

            vfloat32m1_t v_term = __riscv_vfdiv_vv_f32m1(vdx, v_denom);

            vfloat32m1_t v_sum = __riscv_vfmsum_vv_f32m1(v_sum, v_term);

            float f_sum = __riscv_vfmv_f_f_v(v_sum);
            pi += f_sum;

            i += vlen;
        }

        pi_acc += pi * 4.0;
        dummy(NULL, NULL, NULL, NULL, NULL, pi);
    }

    x[0] = pi_acc / (real_t)iterations_val;

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

