real_t basic_pi_reduce(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    real_t dx = 1.0 / (real_t)LEN_1D;
    real_t pi_acc = 0.0;
    int iterations_count = iterations;
    int len = LEN_1D;

    // Determine maximum vector length for float32
    int vl = __riscv_vsetvlmax_e32f();
    if (vl > len) vl = len;

    for (int nl = 0; nl < iterations_count; nl++) {
        real_t pi = 0.0;
        int i = 0;

        while (i < len) {
            int vlen = vl;
            if (i + vlen > len) {
                vlen = len - i;
            }

            // Set vector length
            __riscv_vsetvl(vlen);

            // Generate indices 0..vlen-1 using vseq
            vint32_t vidx = __riscv_vseq(vlen, 0);

            // Convert to float
            vfloat32_t vidx_float = __riscv_vfcvt_f_x(vidx, 0);

            // Add 0.5
            vfloat32_t vhalf = __riscv_vfmv_v_f(0.5f);
            vfloat32_t xv_base = __riscv_vfadd_v_f(vidx_float, vhalf);

            // Multiply by dx
            vfloat32_t xv = __riscv_vfmul_v_f(xv_base, dx);

            // Compute 1 / (1 + xv^2)
            vfloat32_t xv_sq = __riscv_vfmul_v_v(xv, xv);
            vfloat32_t one = __riscv_vfmv_v_f(1.0f);
            vfloat32_t denom = __riscv_vfadd_v_f(xv_sq, one);
            vfloat32_t inv_denom = __riscv_vfdiv_v_f(denom, one);

            // Multiply by dx
            vfloat32_t term = __riscv_vfmul_v_f(inv_denom, dx);

            // Sum the vector
            float sum_chunk = __riscv_vsum_vf_f32(term);

            pi += sum_chunk;

            i += vlen;
        }

        pi_acc += pi * 4.0;
        dummy(NULL, NULL, NULL, NULL, NULL, pi);
    }

    x[0] = pi_acc / (real_t)iterations_count;

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

