        size_t rem = LEN_1D % vec_len;

        // Process full vector elements
        for (size_t i = 0; i < num_vecs; i++) {
            vint32m1_t vec = __riscv_vld1_vx(vint32m1_t *, (Index_type *)idx_list + i * vl, vl);
            vint32m1_t sum_vec = __riscv_vadd_vv(vec, vec);
            vint32m1_t min_vec = __riscv_vmin_vv(vec, vec);
            vint32m1_t max_vec = __riscv_vmax_vv(vec, vec);

            // Reduce sum to scalar
            s += __riscv_vsum_vlseg1_vx_m(vint32m1_t, sum_vec, 0, vl);

            // Reduce min/max to scalar
            Index_type cur_min = __riscv_vmin_vlseg1_vx_m(Index_type, min_vec, 0, vl);
            Index_type cur_max = __riscv_vmax_vlseg1_vx_m(Index_type, max_vec, 0, vl);

            if (cur_min < mn) mn = cur_min;
            if (cur_max > mx) mx = cur_max;
        }

        // Process remaining elements
        for (size_t i = 0; i < rem; i++) {
            Index_type v = idx_list[num_vecs * vl + i];
            s += v;
            if (v < mn) mn = v;
            if (v > mx) mx = v;
        }

        vsum = s; vmin = mn; vmax = mx;
        dummy(NULL, NULL, NULL, NULL, NULL, (real_t)s);
    }
    x[0] = (real_t)vsum / (real_t)LEN_1D;
    x[1] = (real_t)vmin / (real_t)LEN_1D;
    x[2] = (real_t)vmax / (real_t)LEN_1D;

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

