real_t basic_reduce_struct(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    real_t xsum = 0, ysum = 0;
    real_t xmin = x[0], xmax = x[0], ymin = y[0], ymax = y[0];

    // Determine vector length based on data size and hardware capabilities
    size_t vl = vlen();
    size_t vec_len = (LEN_1D + vl - 1) / vl;
    size_t i0 = 0;

    // Initialize vector registers with first element
    vsetvl_e32m1(vl, vec_len);
    vfloat32m1_t vx0 = vld1_vf_f32(x, 0);
    vfloat32m1_t vy0 = vld1_vf_f32(y, 0);

    // Initialize accumulators in vector registers
    vfloat32m1_t vxs = vzero_v();
    vfloat32m1_t vys = vzero_v();
    vfloat32m1_t vxmin = vx0;
    vfloat32m1_t vxmax = vx0;
    vfloat32m1_t vymin = vy0;
    vfloat32m1_t vyx = vy0;

    // Process data in vector chunks
    for (size_t i = 0; i < vec_len; i++) {
        vfloat32m1_t vx = vld1_vf_f32(x, i0);
        vfloat32m1_t vy = vld1_vf_f32(y, i0);

        // Add to sums
        vxs = vadd_vv_f32(vxs, vx);
        vys = vadd_vv_f32(vys, vy);

        // Find min/max for x
        vxmin = vmin_vvv_f32(vx, vxmin, vx0);
        vxmax = vmax_vvv_f32(vx, vxmax, vx0);

        // Find min/max for y
        vymin = vmin_vvv_f32(vy, vymin, vy0);
        vyx = vmax_vvv_f32(vy, vyx, vy0);

        i0 += vl;
    }

    // Handle remaining elements if any
    if (i0 < LEN_1D) {
        vfloat32m1_t vx = vld1_vf_f32(x, i0);
        vfloat32m1_t vy = vld1_vf_f32(y, i0);

        vxs = vadd_vv_f32(vxs, vx);
        vys = vadd_vv_f32(vys, vy);

        vxmin = vmin_vvv_f32(vx, vxmin, vx0);
        vxmax = vmax_vvv_f32(vx, vxmax, vx0);

        vymin = vmin_vvv_f32(vy, vymin, vy0);
        vyx = vmax_vvv_f32(vy, vyx, vy0);
    }

    // Convert vector results to scalar
    real_t xs = vmv_f_f(vxs);
    real_t ys = vmv_f_f(vys);
    real_t xn = vmv_f_f(vxmin);
    real_t xx_ = vmv_f_f(vxmax);
    real_t yn = vmv_f_f(vymin);
    real_t yx = vmv_f_f(vyx);

    // Update running totals across iterations
    for (int nl = 0; nl < iterations; nl++) {
        xsum += xs;
        ysum += ys;
        if (xn < xmin) xmin = xn;
        if (xx_ > xmax) xmax = xx_;
        if (yn < ymin) ymin = yn;
        if (yx > ymax) ymax = yx;

        dummy(x, y, NULL, NULL, NULL, xs);
    }

    z[0] = xsum / (real_t)LEN_1D;
    z[1] = xmin;
    z[2] = xmax;
    z[3] = ysum / (real_t)LEN_1D;
    z[4] = ymin;
    z[5] = ymax;

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

