real_t basic_trap_int(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    real_t x0 = 0.0, h = 1.0 / (real_t)LEN_1D;
    real_t yp = 1.0, ypoint = 1.0;
    real_t acc = 0.0;
    int iterations_val = iterations;
    int len_val = LEN_1D;

    // Determine vector length
    int vl = __riscv_vsetvlmax();
    int vlen = __riscv_vsetvl(vl, __riscv_vtype());
    int vlen_bits = __riscv_vlenbits();
    int num_vecs = (len_val + vlen - 1) / vlen;

    for (int nl = 0; nl < iterations_val; nl++) {
        real_t sumx = 0.0;
        vfloat32m1_t acc_vec = __riscv_vfmv_v_f(vlen_bits, 0.0f);

        for (int v = 0; v < num_vecs; v++) {
            int vl_curr = __riscv_vsetvl(vl, __riscv_vtype());
            vfloat32m1_t idx_vec = __riscv_vmv_v_x(vl_curr, v);
            vfloat32m1_t h_vec = __riscv_vfmv_v_f(vl_curr, h);
            vfloat32m1_t x0_vec = __riscv_vfmv_v_f(vl_curr, x0);

            vfloat32m1_t xv_vec = __riscv_vfadd_vv(vl_curr, x0_vec, h_vec, idx_vec);
            vfloat32m1_t half_vec = __riscv_vfmv_v_f(vl_curr, 0.5f);
            vfloat32m1_t xv_minus_half_vec = __riscv_vfsub_vv(vl_curr, xv_vec, half_vec, xv_vec);
            vfloat32m1_t xv_sq_vec = __riscv_vfmul_vv(vl_curr, xv_minus_half_vec, xv_minus_half_vec);

            vfloat32m1_t yp_vec = __riscv_vfmv_v_f(vl_curr, yp);
            vfloat32m1_t ypoint_vec = __riscv_vfmv_v_f(vl_curr, ypoint);
            vfloat32m1_t ypoint_minus_yp_vec = __riscv_vfsub_vv(vl_curr, ypoint_vec, yp_vec);
            vfloat32m1_t ydiff_sq_vec = __riscv_vfmul_vv(vl_curr, ypoint_minus_yp_vec, ypoint_minus_yp_vec);

            vfloat32m1_t denom_vec = __riscv_vfadd_vv(vl_curr, xv_sq_vec, ydiff_sq_vec);
            vfloat32m1_t one_vec = __riscv_vfmv_v_f(vl_curr, 1.0f);
            vfloat32m1_t denom_plus_one_vec = __riscv_vfadd_vv(vl_curr, denom_vec, one_vec);

            vfloat32m1_t sqrt_denom_vec = __riscv_vfsqrt_vf(vl_curr, denom_plus_one_vec, one_vec);
            vfloat32m1_t inv_sqrt_vec = __riscv_vfdiv_vf(vl_curr, one_vec, sqrt_denom_vec);

            acc_vec = __riscv_vfadd_vv(vl_curr, acc_vec, inv_sqrt_vec);
        }

        vfloat32m1_t final_acc_vec = __riscv_vfmv_f_v(vlen_bits, acc_vec);
        sumx = final_acc_vec;
        acc += sumx;
        dummy(NULL, NULL, NULL, NULL, NULL, sumx);
    }

    x[0] = acc / (real_t)(iterations_val * len_val);

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

