real_t lcals_eos(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    real_t r = 0.5, t = 0.25, q = 0.125;
    const int vlen = __riscv_vget_vlen();
    const int vlen_b = vlen * sizeof(real_t);
    const int step = vlen;
    const int mask = (LEN_1D - 6) / step;
    const int rem = (LEN_1D - 6) % step;

    for (int nl = 0; nl < iterations; nl++) {
        for (int i = 0; i < mask; i++) {
            real_t *v_ui = u + i * step;
            real_t *v_ui1 = v_ui + 1;
            real_t *v_ui2 = v_ui1 + 1;
            real_t *v_ui3 = v_ui2 + 1;
            real_t *v_ui4 = v_ui3 + 1;
            real_t *v_ui5 = v_ui4 + 1;
            real_t *v_ui6 = v_ui5 + 1;

            real_t *v_yi = y + i * step;
            real_t *v_zi = z + i * step;
            real_t *v_xi = x + i * step;

            vreal_t v_ui_vec = __riscv_vle16_v(v_ui, vlen_b);
            vreal_t v_ui1_vec = __riscv_vle16_v(v_ui1, vlen_b);
            vreal_t v_ui2_vec = __riscv_vle16_v(v_ui2, vlen_b);
            vreal_t v_ui3_vec = __riscv_vle16_v(v_ui3, vlen_b);
            vreal_t v_ui4_vec = __riscv_vle16_v(v_ui4, vlen_b);
            vreal_t v_ui5_vec = __riscv_vle16_v(v_ui5, vlen_b);
            vreal_t v_ui6_vec = __riscv_vle16_v(v_ui6, vlen_b);
            vreal_t v_yi_vec = __riscv_vle16_v(v_yi, vlen_b);
            vreal_t v_zi_vec = __riscv_vle16_v(v_zi, vlen_b);

            vreal_t term1 = __riscv_vfmadd_vf_v(v_ui_vec, __riscv_vfmv_v_f(r), v_ui1_vec);
            vreal_t term2 = __riscv_vfmadd_vf_v(v_ui1_vec, __riscv_vfmv_v_f(r), v_ui2_vec);
            vreal_t term3 = __riscv_vfmadd_vf_v(v_ui2_vec, __riscv_vfmv_v_f(r), v_ui3_vec);
            vreal_t term4 = __riscv_vfmadd_vf_v(v_ui3_vec, __riscv_vfmv_v_f(r), v_ui4_vec);
            vreal_t term5 = __riscv_vfmadd_vf_v(v_ui4_vec, __riscv_vfmv_v_f(q), v_ui5_vec);
            vreal_t term6 = __riscv_vfmadd_vf_v(v_ui5_vec, __riscv_vfmv_v_f(q), v_ui6_vec);

            vreal_t inner = __riscv_vfadd_vv(term4, term5);
            inner = __riscv_vfadd_vv(inner, term6);
            inner = __riscv_vfmadd_vf_v(v_ui3_vec, __riscv_vfmv_v_f(t), inner);
            inner = __riscv_vfmadd_vf_v(v_ui2_vec, __riscv_vfmv_v_f(r), inner);
            inner = __riscv_vfmadd_vf_v(v_ui1_vec, __riscv_vfmv_v_f(t), inner);

            vreal_t final = __riscv_vfadd_vv(v_ui_vec, inner);
            final = __riscv_vfadd_vv(final, v_zi_vec);
            final = __riscv_vfmadd_vf_v(final, __riscv_vfmv_v_f(r), v_yi_vec);

            __riscv_vse16_v(v_xi, final);
        }

        if (rem > 0) {
            for (int j = 0; j < rem; j++) {
                int idx = mask * step + j;
                x[idx] = u[idx] + r*( z[idx] + r*y[idx] ) +
                          t*( u[idx+3] + r*( u[idx+2] + r*u[idx+1] ) +
                             t*( u[idx+6] + q*( u[idx+5] + q*u[idx+4] ) ) );
            }
        }

        dummy(x, u, y, z, NULL, q);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

