real_t lcals_first_diff(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    for (int nl = 0; nl < iterations; nl++) {
        Index_type len = LEN_1D - 1;
        Index_type vl = __riscv_vsetvlmax();
        Index_type i = 0;

        while (i < len) {
            Index_type vl_actual = (i + vl > len) ? (len - i) : vl;
            vfloat64_t vd = __riscv_vleif_v_f64m1(vl_actual, y + i);
            vfloat64_t vs1 = __riscv_vleif_v_f64m1(vl_actual, y + i + vl_actual);
            vfloat64_t vd_new = __riscv_vsub_vv_f64m1(vs1, vd);
            __riscv_vseif_v_f64m1(vd_new, x + i, vl_actual);
            i += vl_actual;
        }
        dummy(x, y, NULL, NULL, NULL, 0.0);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

