real_t lcals_first_min(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    Index_type loc = 0;
    real_t mn = x[0];
    for (int nl = 0; nl < iterations; nl++) {
        loc = 0; mn = x[0];

        // Determine vector length
        size_t vl = vsetvl_e32f(LEN_1D);
        vfloat32m1_t vmin = vfmv_v_f_f(vl, mn);
        vint32m1_t vloc = vfmv_v_x_f(vl, 0);
        vfloat32m1_t vx = vle8_v_f(vl, (vint8m1_t)x);

        // Process in vector chunks
        for (; vl > 0; vl = vsetvl_e32f(LEN_1D - (LEN_1D - vl))) {
            vfloat32m1_t vcomp = vfmv_v_f_f(vl, mn);
            vint32m1_t vidx = vseq_v_v_x(vl, vx, vmin);
            vint32m1_t vnewloc = vslide1up_v_v_x(vl, vloc, vidx);
            vfloat32m1_t vnewmn = vmin_v_v_f(vl, vx, vmin);
            vloc = vslide1up_v_v_x(vl, vloc, vidx);
            vmin = vmin_v_v_f(vl, vx, vmin);

            // Reduce: find first index where condition is true
            vint32m1_t vfirst = vfirst_v_v_x(vl, vidx);
            vint32m1_t vfinalloc = vslide1up_v_v_x(vl, vloc, vfirst);
            vloc = vslide1up_v_v_x(vl, vloc, vfirst);

            // Update scalar min if any element was smaller
            vfloat32m1_t vany = vany_v_v_x(vl, vidx);
            if (vany[0] != 0) {
                vint32m1_t vfirst_idx = vfirst_v_v_x(vl, vidx);
                vint32m1_t vfirst_val = vslide1up_v_v_x(vl, vloc, vfirst_idx);
                vloc = vslide1up_v_v_x(vl, vloc, vfirst_idx);
                vmin = vmin_v_v_f(vl, vx, vmin);
            }
        }

        // Handle remaining scalar elements if any
        for (Index_type i = 0; i < LEN_1D; i += 32) {
            if (i + 32 > LEN_1D) {
                for (Index_type j = i; j < LEN_1D; j++) {
                    if (x[j] < mn) {
                        mn = x[j];
                        loc = j;
                    }
                }
            } else {
                for (Index_type j = i; j < i + 32; j++) {
                    if (x[j] < mn) {
                        mn = x[j];
                        loc = j;
                    }
                }
            }
        }

        dummy(x, NULL, NULL, NULL, NULL, mn);
    }
    y[0] = mn;
    y[1] = (real_t)loc / (real_t)LEN_1D;

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

