real_t lcals_first_sum(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    for (int nl = 0; nl < iterations; nl++) {
        size_t len = (size_t)LEN_1D;
        size_t vl = __riscv_vsetvlmax();
        if (vl >= len) vl = len - 1;

        vint8m1_t *vx = (vint8m1_t *)x;
        vint8m1_t *vy = (vint8m1_t *)y;

        for (size_t i = 1; i < len; i += vl) {
            vint8m1_t vx_i = __riscv_vle8_v(vl, &x[i]);
            vint8m1_t vy_i = __riscv_vle8_v(vl, &y[i]);
            vint8m1_t vy_prev = __riscv_vle8_v(vl, &y[i-1]);

            vint8m1_t sum = __riscv_vadd_vv(vy_prev, vy_i);
            __riscv_vse8_v(vl, sum, &x[i]);
        }

        dummy(x, y, NULL, NULL, NULL, 0.0);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

