real_t lcals_gen_lin_recur(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    Index_type kb5i = 0;
    int iterations_16 = iterations / 16 + 1;

    // Determine vector length
    size_t vl = __riscv_vsetvlmax();
    if (vl > LEN_1D) vl = LEN_1D;
    if (vl == 0) vl = 1; // Fallback if VL is 0

    for (int nl = 0; nl < iterations_16; nl++) {
        // Inner loop: k from 0 to LEN_1D-1
        // b5[k+kb5i] = sa[k] + stb5[k]*sb[k];
        // stb5[k] = b5[k+kb5i] - stb5[k];

        vfloat64_t vsa = __riscv_vleig_f64m1(vl, sa);
        vfloat64_t vstb5 = __riscv_vleig_f64m1(vl, stb5);
        vfloat64_t vsb = __riscv_vleig_f64m1(vl, sb);

        vfloat64_t vprod = __riscv_vfmul_v_f_f(vl, vstb5, vsb);
        vfloat64_t vsum = __riscv_vfadd_v_f_f(vl, vsa, vprod);
        __riscv_vseig_f64m1(vl, vsum, b5 + kb5i);

        // stb5[k] = b5[k+kb5i] - stb5[k] -> vsum - vstb5[k]
        vfloat64_t vdiff = __riscv_vfsub_v_f_f(vl, vsum, vstb5);
        vstb5 = __riscv_vseig_f64m1(vl, vdiff, stb5);

        // Handle tail if LEN_1D is not multiple of VL
        Index_type rem = LEN_1D % vl;
        if (rem > 0) {
            for (Index_type k = 0; k < rem; ++k) {
                b5[k+kb5i] = sa[k] + stb5[k]*sb[k];
                stb5[k] = b5[k+kb5i] - stb5[k];
            }
        }

        // Second loop: i from 1 to LEN_1D, k = LEN_1D - i
        // This is equivalent to k from LEN_1D-1 down to 0
        // We can reuse the same vector logic

        vsa = __riscv_vleig_f64m1(vl, sa);
        vstb5 = __riscv_vleig_f64m1(vl, stb5);
        vsb = __riscv_vleig_f64m1(vl, sb);

        vprod = __riscv_vfmul_v_f_f(vl, vstb5, vsb);
        vsum = __riscv_vfadd_v_f_f(vl, vsa, vprod);
        __riscv_vseig_f64m1(vl, vsum, b5 + kb5i);

        vdiff = __riscv_vfsub_v_f_f(vl, vsum, vstb5);
        vstb5 = __riscv_vseig_f64m1(vl, vdiff, stb5);

        rem = LEN_1D % vl;
        if (rem > 0) {
            for (Index_type k = 0; k < rem; ++k) {
                b5[k+kb5i] = sa[k] + stb5[k]*sb[k];
                stb5[k] = b5[k+kb5i] - stb5[k];
            }
        }

        dummy(b5, stb5, sa, sb, NULL, 0.0);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

