real_t lcals_hydro_1d(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    real_t q = 0.5, r = 0.25, t = 0.125;
    size_t len = LEN_1D - 12;
    size_t vl = __riscv_vsetvlmax();
    size_t nvec = len / vl;
    size_t rem = len % vl;

    for (int nl = 0; nl < iterations; nl++) {
        real_t *vq = __riscv_vld(&q, vl);
        real_t *vr = __riscv_vld(&r, vl);
        real_t *vt = __riscv_vld(&t, vl);

        for (size_t i = 0; i < nvec; i++) {
            real_t *z_base = &z[i * vl];
            real_t *z_next10 = __riscv_vle(vl, &z_base[10]);
            real_t *z_next11 = __riscv_vle(vl, &z_base[11]);
            real_t *y_v = __riscv_vle(vl, &y[i * vl]);

            real_t *term1 = __riscv_vfmul_vv(vl, z_next10, vr);
            real_t *term2 = __riscv_vfmul_vv(vl, z_next11, vt);
            real_t *sum = __riscv_vfadd_vv(vl, term1, term2);
            real_t *prod = __riscv_vfmul_vv(vl, y_v, sum);
            real_t *x_v = __riscv_vfadd_vv(vl, vq, prod);
            __riscv_vse(x_v, &x[i * vl]);
        }

        if (rem > 0) {
            size_t i = nvec * vl;
            for (size_t j = 0; j < rem; j++) {
                x[i + j] = q + y[i + j] * (r * z[i + j + 10] + t * z[i + j + 11]);
            }
        }

        dummy(x, y, z, NULL, NULL, q);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

