            vfloat32_t exp_y_minus_1 = vsub_v_f32m1(exp_y, one, count);

            // Compute w[i] = x[i] / (expf(y[i]) - 1.0f)
            vfloat32_t wx = vdiv_v_f32m1(vx, exp_y_minus_1, count);

            // Store result
            vse_v_f32m1(w + i, wx, count);

            // Update y for next iteration (y[i] = u[i] / v[i])
            vse_v_f32m1(y + i, vy_new, count);
        }

        dummy(y, w, u, v, x, 0.0);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
