        real_t local = 0.0;
        const int vlen_elems_actual = (LEN_1D < vlen_elems) ? LEN_1D : vlen_elems;
        const int vlen_actual = vlen_elems_actual * sizeof(real_t);

        vfloat32m1_t va = __riscv_vleig_v_fv(vlen_actual, a);
        vfloat32m1_t vb = __riscv_vleig_v_fv(vlen_actual, b);
